  "program": "; RUN 하면 제어 데이터와 보낼 글자를 준비한다\nLD SM402\nMOV K1 D100\nMOV K5 D102\n$MOV \"HELLO\" D200\n\n; 버튼을 누르는 순간, 송신 중이 아니면 보낸다\n@X0 송신 버튼\n@X62 송신 처리 중\nLDP X0\nANI X62\nG.OUTPUT U6 D100 D200 M0\nEND",
