  "desc": "버튼을 두 번 누르면 카운터 C0 의 현재값이 2 가 됩니다. 완료 디바이스 M0 은 1스캔만 ON 되므로 디바이스 모니터로는 잡기 어렵습니다 — 이렇게 카운터나 SET 으로 받아 두어야 합니다.정상이면 D101(결과)이 0 입니다. 0 이 아니면 그 값이 에러 코드입니다.",
  "rack": "",
  "io": "PB START X0 label=송신 color=green\nSEL SW1 X2 txt=NG/OK label=판정 결과\nPB CNT X3 label=제품 감지 color=blue\nTERM PC1 port=CH1 label=PC 터미널\nLAMP TXOK Y21 color=green label=송신 완료\nLAMP TXNG Y22 color=red label=송신 이상",
  "program": "; 송신 준비\nLD SM402\nMOV K1 D100\nMOV K5 D102\n$MOV \"HELLO\" D200\n\n; 버튼 상승에서 송신 요구\nLDP X0\nANI X62\nG.OUTPUT U6 D100 D200 M0\n\n; 정상으로 끝나면 송신 횟수를 센다\n@M0 송신 완료\n@M1 송신 이상\nLD M0\nANI M1\nOUT C0 K10\n\n; 이상으로 끝나면 경보등을 세트\nLD M1\nSET Y22\nEND",
  "test": "START=1 -> PC1~HELLO CN0=1\nSTART=0 -> CN0=1\nSTART=1 -> CN0=2 Y22=0",
