  "desc": "판정 결과 스위치를 OK 쪽으로 두고 버튼을 누르면 OK, NG 쪽이면 NG 가 갑니다. MPS · MPP 로 같은 조건에서 두 갈래로 나눴습니다 (8장).순서가 중요합니다 — 글자를 고르는 회로가 G.OUTPUT 보다 위에 있어야 같은 스캔에서 바뀐 글자가 나갑니다.",
