  "io": "PB START X0 label=송신 color=green\nSEL SW1 X2 txt=NG/OK label=판정 결과\nPB CNT X3 label=제품 감지 color=blue\nTERM PC1 port=CH1 label=PC 터미널\nLAMP TXOK Y21 color=green label=송신 완료\nLAMP TXNG Y22 color=red label=송신 이상",
  "program": "; 공통 제어 데이터 (두 글자)\nLD SM402\nMOV K1 D100\nMOV K2 D102\n\n; 버튼을 누르는 순간 판정 스위치를 보고 글자를 고른다\nLDP X0\nMPS\nAND X2\n$MOV \"OK\" D200\nMPP\nANI X2\n$MOV \"NG\" D200\n\n; 고른 글자를 보낸다\nLDP X0\nANI X62\nG.OUTPUT U6 D100 D200 M0\nEND",
